head.script:
scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof generator1 !== 'undefined') {
        generator1.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // Generator 컴포넌트의 자식인 gridLayout 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strGenerator = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strGenerator += '<w2:generator ' +strNameSpace+ ' id="generator1">';
    strGenerator += '<w2:gridLayout id="generator1_child" style="width:400px; height:200px; background-color:silver; border:1px solid #888888;" gridTemplateColumns="1fr 1fr;" gridTemplateRows="40px 40px 40px;" gridColumnGap="1px;" gridRowGap="1px;" gridColumn="1:1:1:2:2:2;" gridRow="1:2:3:1:2:3;" rowShow="1:1:1:1:1:1;" ev:onclick="scwin.generator1_child_onclick">';
    strGenerator += '</w2:gridLayout>';
    strGenerator += '</w2:generator>';

    scwin.generator1 = await $p.dynamicCreate(
        "generator1",
        "generator",
        strGenerator,
        grp_comp
    );

    scwin.generator1.insertChild();

    // Generator 컴포넌트의 자식이 아닌 gridLayout (target1, 회색 배경) — 비교용
    let strTarget = '';
    strTarget += '<w2:gridLayout ' + strNameSpace + ' ev:onclick="scwin.target1_onclick" style="width:400px; height:200px; background-color:silver; border:1px solid #888888;" gridTemplateColumns="1fr 1fr;" gridTemplateRows="40px 40px 40px;" gridColumnGap="1px;" gridRowGap="1px;" gridColumn="1:1:1:2:2:2;" gridRow="1:2:3:1:2:3;" rowShow="1:1:1:1:1:1;">';
    strTarget += '</w2:gridLayout>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridLayout",
        strTarget,
        grp_comp
    );
}
